import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

import time

def get_best_schedule(workload, num_seqs):
    """
    Conflict-window-block-packing seed + ruin-and-recreate polish.

    Approach: (1) build per-transaction key sets and a conflict graph,
    partitioning transactions into connected components via union-find on
    shared keys; (2) order each component — exhaustive enumeration only for
    tiny clusters (<= 5 txns, under a tight build budget) and greedy
    insertion at true-best position otherwise; (3) interleave cluster
    orders by repeatedly appending the cluster head whose prefix minimises
    the true simulator cost, handling cross-cluster coupling; (4) polish
    with the ruin-and-recreate loop (conflict-linked or window ruin,
    best-position reinsertion with adjacent-swap repair, segment-reversal
    descent on stall) seeded from the best of the identity and
    cluster-packed schedules. The build phase is deliberately cheap so the
    polish loop — which produced the strongest prior results — receives
    most of the ~95s per-workload budget. Tuple-key cost cache and
    identity fallback guarantee validity and the 360s limit.
    """
    n = workload.num_txns
    if n == 0:
        return 0, []
    deadline = time.time() + 95.0
    build_deadline = time.time() + 15.0
    cache = {}

    def cost(seq):
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = workload.get_opt_seq_cost(list(seq))
            cache[key] = c
        return c

    # Fallback: identity permutation (always valid).
    best_seq = list(range(n))
    best_cost = cost(best_seq)

    # ---- Conflict structure: per-txn key sets and union-find components ----
    txn_keys = {}
    try:
        for t in range(n):
            keys = set()
            for op in workload.get_txn_ops(t):
                try:
                    keys.add(op.key)
                except AttributeError:
                    try:
                        keys.add(op[1])
                    except Exception:
                        pass
            txn_keys[t] = keys
    except Exception:
        txn_keys = {}

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    if txn_keys:
        key_owner = {}
        for t in range(n):
            for k in txn_keys.get(t, ()):
                if k in key_owner:
                    ra, rb = find(t), find(key_owner[k])
                    if ra != rb:
                        parent[ra] = rb
                else:
                    key_owner[k] = t

    clusters = {}
    for t in range(n):
        clusters.setdefault(find(t), []).append(t)
    comp_lists = [sorted(members) for members in clusters.values()]

    def order_cluster(members):
        """Exhaustive order for tiny clusters (build-budget guarded);
        greedy insertion at true-best position for larger ones."""
        m = len(members)
        if m <= 1:
            return members[:]
        if m <= 5 and time.time() < build_deadline:
            from itertools import permutations
            best, best_c = None, None
            for perm in permutations(members):
                c = cost(list(perm))
                if best_c is None or c < best_c:
                    best_c, best = c, perm
                if time.time() > build_deadline:
                    break
            if best is not None:
                return list(best)
        cur = []
        for t in members:
            best_pos, best_c = 0, None
            for pos in range(len(cur) + 1):
                cand = cur[:pos] + [t] + cur[pos:]
                c = cost(cand)
                if best_c is None or c < best_c:
                    best_c, best_pos = c, pos
                if time.time() > build_deadline:
                    break
            cur.insert(best_pos, t)
        return cur

    cluster_orders = [order_cluster(m) for m in comp_lists]

    # ---- Interleave cluster orders by true prefix cost ----
    seq = []
    heads = [0] * len(cluster_orders)
    while len(seq) < n and time.time() < build_deadline:
        best_choice, best_c = None, None
        for ci in range(len(cluster_orders)):
            if heads[ci] < len(cluster_orders[ci]):
                cand_seq = seq + [cluster_orders[ci][heads[ci]]]
                c = cost(cand_seq)
                if best_c is None or c < best_c:
                    best_c, best_choice = c, ci
        if best_choice is None:
            break
        seq.append(cluster_orders[best_choice][heads[best_choice]])
        heads[best_choice] += 1
    # Complete any leftovers (build deadline hit) deterministically.
    for ci in range(len(cluster_orders)):
        while heads[ci] < len(cluster_orders[ci]):
            seq.append(cluster_orders[ci][heads[ci]])
            heads[ci] += 1

    if len(set(seq)) == n:
        c = cost(seq)
        if c < best_cost:
            best_cost, best_seq = c, list(seq)

    # ---- Ruin-and-recreate polish (bulk of budget) ----
    def ruin_block(cur_seq):
        """Pick a block to remove: conflict-linked cluster or random window."""
        if txn_keys and random.random() < 0.5:
            seed = random.randrange(n)
            block = {seed}
            seed_keys = txn_keys.get(seed, set())
            for t in range(n):
                if t != seed and txn_keys.get(t, set()) & seed_keys:
                    block.add(t)
                    if len(block) >= 25:
                        break
            if len(block) < 3:
                return None
            return [t for t in cur_seq if t in block]
        lo = random.randrange(n)
        size = random.randint(10, min(25, n))
        hi = min(n, lo + size)
        return cur_seq[lo:hi]

    def recreate(cur, removed):
        """Reinsert each removed txn at its true-best position, then run one
        adjacent-swap repair pass before the accept test."""
        for t in removed:
            best_pos, best_c = None, None
            for pos in range(len(cur) + 1):
                cand = cur[:pos] + [t] + cur[pos:]
                c = cost(cand)
                if best_c is None or c < best_c:
                    best_c, best_pos = c, pos
                if time.time() > deadline:
                    break
            cur = cur[:best_pos] + [t] + cur[best_pos:]
        base = cost(cur)
        for i in range(len(cur) - 1):
            if time.time() > deadline:
                break
            cand = cur[:]
            cand[i], cand[i + 1] = cand[i + 1], cand[i]
            c = cost(cand)
            if c < base:
                cur, base = cand, c
        return cur

    def reversal_descent(s, c):
        """First-improvement descent over segment reversals (lengths 2-6):
        fixes conflict-linked blocks whose mutual order is backwards — a
        state insertion-only moves cannot escape."""
        stall = False
        while not stall and time.time() < deadline:
            stall = True
            for i in range(n - 1):
                if time.time() > deadline:
                    return s, c
                for ln in (2, 3, 4, 5, 6):
                    j = i + ln
                    if j >= n:
                        break
                    cand = s[:i] + s[i:j + 1][::-1] + s[j + 1:]
                    cc = cost(cand)
                    if cc < c:
                        s, c = cand, cc
                        stall = False
                        break
        return s, c

    cur_seq, cur_cost = best_seq[:], best_cost
    stall_count = 0
    while time.time() < deadline:
        removed = ruin_block(cur_seq)
        if not removed:
            continue
        rem_set = set(removed)
        partial = [t for t in cur_seq if t not in rem_set]
        cand = recreate(partial, removed)
        c = cost(cand)
        if c < cur_cost:
            cur_seq, cur_cost = cand, c
            stall_count = 0
            if c < best_cost:
                best_cost, best_seq = c, cand[:]
        elif c == cur_cost and random.random() < 0.3:
            # Plateau drift across equal-cost states.
            cur_seq, cur_cost = cand, c
        else:
            stall_count += 1
            if stall_count >= 40:
                cur_seq, cur_cost = reversal_descent(cur_seq[:], cur_cost)
                stall_count = 0
                if cur_cost < best_cost:
                    best_cost, best_seq = cur_cost, cur_seq[:]
            elif random.random() < 0.05:
                cur_seq, cur_cost = best_seq[:], best_cost

    assert len(set(best_seq)) == n
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")

